describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow();
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 600 },
            ],
            900,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 5000),
      ).toBe(0);
    });

    it("selects first bracket (weight exactly at boundary 500g)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(300);
    });

    it("selects first bracket (weight below 500g)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 200, 1)], 5000),
      ).toBe(300);
    });

    it("selects second bracket (weight 501-1000g)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
      ).toBe(500);
    });

    it("selects second bracket (weight exactly 1000g)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1)], 5000),
      ).toBe(500);
    });

    it("selects third bracket (weight 1001-2000g)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1500, 1)], 5000),
      ).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 2500, 1)], 5000),
      ).toBe(1200);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      expect(
        noOverflow.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(600);
    });

    it("sums weight across multiple lines", () => {
      // 300*2 + 200*3 = 600 + 600 = 1200g → third bracket (≤2000)
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 3)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(800);
    });
  });
});

