import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";
import type {
  PriceFetcher,
  InventoryChecker,
  InventoryDecision,
} from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = {
  id: "b",
  name: "Gadget",
  unitPriceCents: 2000,
  weightGrams: 500,
};

describe("Cart - line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity sets quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 3)).toThrow();
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    (snap as CartLine[])[0].quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart - totals / pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("applies discount policy to subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 9999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);

    const negativeDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart2 = new Cart({ discountPolicy: negativeDiscount });
    cart2.add(productA, 1);
    expect(cart2.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
    const totals = cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("computes shipping against lines and discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 100,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000, discounted 900
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 80,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800, tax 80, shipping 500
    const totals = cart.totals();
    expect(totals.totalCents).toBe(800 + 80 + 500);
  });

  it("empty cart produces all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("defaults region to US", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
      expect.any(Number),
      "US",
    );
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart - checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InstanceType<typeof InventoryError>;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } as InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InstanceType<typeof InventoryError>;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes inventory check when available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 0,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(1000 * 0.1) = 100
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("asyncTaxProvider composes with discount and shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 300,
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(800 * 0.05) = 40
    expect(result.totals.taxCents).toBe(40);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(800 + 40 + 300);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("checks all items in inventory (first denial wins)", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation((id: string) => {
        if (id === "a") return Promise.resolve({ available: true });
        return Promise.resolve({ available: false, reason: "no stock" });
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("combines priceFetcher and inventoryChecker", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000); // 500 * 2
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });
});

